// ─── 公共接口 ───

export interface PublicationConfig {
  name: string;
  label: string;
  type: "newspaper" | "magazine";
  defaultId: string;
  seqConfig?: Record<string, number[]>;
  genSeqText?: (seq: number) => string;
  disabledDate?: (dateStr: string) => boolean;
  pageOutlineAvailable?: (id: string) => boolean;
  enableTextLayer?: boolean;
  resolutionControl?: boolean;
}

function genSeqTextDefault(seq: number): string {
  if (seq > 90) return '增刊' + (seq % 90);
  return '第' + seq + '期';
}

function isDateDisabled(dateStr: string, config: {
  minDate?: string; maxDate?: string;
  missingYears?: number[];
  blacklist?: number[];
  missingRanges?: ReadonlyArray<readonly [string, string]>;
  availableYears?: number[];
  yearRange?: [number, number];
  excludeYear?: number;
}): boolean {
  const d = parseInt(dateStr);
  if (config.minDate && d < parseInt(config.minDate)) return true;
  if (config.maxDate && d > parseInt(config.maxDate)) return true;
  if (config.missingYears?.includes(Math.floor(d / 10000))) return true;
  if (config.blacklist?.includes(d)) return true;
  if (config.missingRanges?.some(([start, end]) => dateStr >= start && dateStr <= end)) return true;
  if (config.availableYears && !config.availableYears.includes(Math.floor(d / 10000))) return true;
  if (config.yearRange) {
    const y = Math.floor(d / 10000);
    if (y < config.yearRange[0] || y > config.yearRange[1]) return true;
  }
  if (config.excludeYear && Math.floor(d / 10000) === config.excludeYear) return true;
  return false;
}

function hasRmrbPageOutline(id: string): boolean {
  const year = Number(id.slice(0, 4));
  return (year >= 1946 && year <= 1947)
    || (year >= 1949 && year <= 2007)
    || (year >= 2011 && year <= 2012);
}

export const PUBLICATIONS: Record<string, PublicationConfig> = {
  rmrb: {
    name: "rmrb", label: "人民日报", type: "newspaper", defaultId: "19761009",
    resolutionControl: true,
    // Audited against representative local issues for every year. Some 2011
    // and 2012 issues still contain only production codes; the reader applies
    // a second content-level filter before showing the outline button.
    pageOutlineAvailable: hasRmrbPageOutline,
    disabledDate: (d) => isDateDisabled(d, {
      minDate: "19460515", maxDate: getLatestRmrbAvailableDate(),
      missingRanges: RMRB_MISSING_RANGES,
    }),
  },
  ckxx: {
    name: "ckxx", label: "参考消息", type: "newspaper", defaultId: "19760910",
    disabledDate: (d) => isDateDisabled(d, {
      minDate: "19570301", maxDate: "19981231",
      blacklist: CKXX_BLACKLIST,
      excludeYear: 1989,
    }),
  },
  hq: {
    name: "hq", label: "红旗", type: "magazine", defaultId: "196419",
    seqConfig: HQ_SEQ, genSeqText: genSeqTextDefault,
    disabledDate: (d) => {
      const y = Math.floor(parseInt(d) / 10000);
      return y < 1958 || y > 1976;
    },
  },
  rmhb: {
    name: "rmhb", label: "人民画报", type: "magazine", defaultId: "197292",
    seqConfig: RMHB_SEQ, genSeqText: genSeqTextDefault,
    disabledDate: (d) => {
      const y = Math.floor(parseInt(d) / 10000);
      if (y < 1950 || y > 1976) return true;
      if (y === 1975) return true;
      return false;
    },
  },
  sjzs: {
    name: "sjzs", label: "世界知识", type: "magazine", defaultId: "196513",
    seqConfig: SJZS_SEQ, genSeqText: genSeqTextDefault,
    enableTextLayer: true,
    disabledDate: (d) => {
      const y = Math.floor(parseInt(d) / 10000);
      const minYear = Math.min(...SJZS_YEARS);
      const maxYear = Math.max(...SJZS_YEARS);
      if (y < minYear || y > maxYear) return true;
      return !SJZS_YEARS.includes(y);
    },
  },
};
